      "keystrokes": "cat > main.cpp <<'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n, m;\n    if(!(cin >> n >> m)) return 0;\n    vector<string> grid(n);\n    int sr = -1, sc = -1;\n    for(int i = 0; i < n; ++i){\n        cin >> grid[i];\n        for(int j = 0; j < m; ++j){\n            if(grid[i][j] == 'S'){\n                sr = i; sc = j; grid[i][j] = '.';\n            }\n        }\n    }\n\n    int N = n * m;\n    const int INF = 1000000000;\n    vector<int> t1x(N, INF), t1y(N, INF), t2x(N, INF), t2y(N, INF);\n    vector<char> cnt(N, 0);\n\n    auto idx = [&](int r, int c){ return r * m + c; };\n    deque<tuple<int,int,int>> q; // (cell_id, tile_x, tile_y)\n    int sidx = idx(sr, sc);\n    t1x[sidx] = 0; t1y[sidx] = 0; cnt[sidx] = 1; q.emplace_back(sidx, 0, 0);\n\n    int dr[4] = {-1, 1, 0, 0};\n    int dc[4] = {0, 0, -1, 1};\n\n    while(!q.empty()){\n        auto [id, tx, ty] = q.front(); q.pop_front();\n        int r = id / m;\n        int c = id % m;\n        for(int k = 0; k < 4; ++k){\n            int nr = r + dr[k];\n            int nc = c + dc[k];\n            int ntx = tx, nty = ty;\n            if(nr < 0){ nr = n - 1; ntx = tx - 1; }\n            else if(nr >= n){ nr = 0; ntx = tx + 1; }\n            if(nc < 0){ nc = m - 1; nty = ty - 1; }\n            else if(nc >= m){ nc = 0; nty = ty + 1; }\n\n            if(grid[nr][nc] == '#') continue;\n            int nid = nr * m + nc;\n            bool exists = (t1x[nid] == ntx && t1y[nid] == nty) || (t2x[nid] == ntx && t2y[nid] == nty);\n            if(exists) continue;\n            if(cnt[nid] == 0){\n                t1x[nid] = ntx; t1y[nid] = nty; cnt[nid] = 1;\n                q.emplace_back(nid, ntx, nty);\n            } else if(cnt[nid] == 1){\n                t2x[nid] = ntx; t2y[nid] = nty; cnt[nid] = 2;\n                cout << \"Yes\\n\";\n                return 0;\n            }\n        }\n    }\n\n    cout << \"No\\n\";\n    return 0;\n}\nCPP\n",
