import random
import subprocess
import sys

def brute_case(s):
    n = len(s)
    pos = [i for i,c in enumerate(s) if c == '?']
    q = len(pos)
    res = set()
    for mask in range(1<<q):
        arr = list(s)
        for j in range(q):
            arr[pos[j]] = 'V' if (mask>>j)&1 else 'K'
        t = ''.join(arr)
        for d in range(1, n+1):
            ok = True
            for i in range(n-d):
                if t[i] != t[i+d]:
                    ok = False
                    break
            if ok:
                res.add(d)
    return sorted(res)


def run_main(n, s):
    input_data = f"1\n{n}\n{s}\n"
    proc = subprocess.run(['./main'], input=input_data.encode(), stdout=subprocess.PIPE)
    out = proc.stdout.decode().strip().split()
    if not out:
        return None
    k = int(out[0])
    periods = list(map(int, out[1:1+k]))
    return periods


def test_once(trials=200):
    for _ in range(trials):
        l = random.randint(1, 12)
        s = ''.join(random.choice(['V','K','?']) for _ in range(l))
        expected = brute_case(s)
        got = run_main(l, s)
        if got != expected:
            print("Mismatch for s=", s)
            print("Expected:", expected)
            print("Got    :", got)
            return False
    return True

if __name__ == '__main__':
    ok = test_once()
    print("OK" if ok else "FAIL")
